const box=document.querySelector('.lightbox'),large=box.querySelector('img');document.querySelectorAll('.gallery img').forEach(img=>img.addEventListener('click',()=>{large.src=img.src;large.alt=img.alt;box.classList.add('open')}));box.addEventListener('click',()=>{box.classList.remove('open');large.removeAttribute('src')});document.addEventListener('keydown',e=>{if(e.key==='Escape')box.click()});
